function verify(records) {
 const cols="ABCDEFGHJ", points=[...cols].flatMap(c=>Array.from({length:9},(_,i)=>c+(i+1)));
 const b=Object.fromEntries(points.map(p=>[p,"."])),captures={X:0,O:0},moves=[],events=[],checks=[];
 let ko=null;
 const adj=p=>{let x=cols.indexOf(p[0]),y=+p[1];return[[x-1,y],[x+1,y],[x,y-1],[x,y+1]].filter(([x,y])=>x>=0&&x<9&&y>=1&&y<=9).map(([x,y])=>cols[x]+y)};
 const group=p=>{const color=b[p],seen=new Set([p]),q=[p],lib=new Set();while(q.length){for(const n of adj(q.pop())){if(b[n]===".")lib.add(n);else if(b[n]===color&&!seen.has(n)){seen.add(n);q.push(n)}}}return{stones:[...seen],liberties:[...lib]}};
 const apply=(color,move)=>{let number=moves.length+1,removed=[];if(move==="pass"){ko=null;}else{if(b[move]!=="."||move===ko)throw Error("Illegal actual move "+number);b[move]=color;for(const n of adj(move)){if(b[n]!=="."&&b[n]!==color){const g=group(n);if(!g.liberties.length){for(const p of g.stones){b[p]=".";removed.push(p)}}}}const own=group(move);if(!own.liberties.length)throw Error("Actual suicide "+number);ko=removed.length===1&&own.stones.length===1&&own.liberties.length===1?removed[0]:null;captures[color]+=removed.length;}
 moves.push({number,color,move});if(removed.length)events.push({number,color,move,removed:removed.sort()});};
 for(let i=0;i<records.length;i++){const r=records[i],s=r.result.content.filter(c=>c.type==="text").map(c=>c.text).join("\n");
  if(r.kind==="mcp__go__play"){const own=s.match(/You played ([A-HJ][1-9])\./);if(r.args.move==="pass"){if(!s.includes("You passed."))throw Error("Missing pass")}else if(!own||own[1]!==r.args.move)throw Error("Move acknowledgement mismatch");apply("X",r.args.move);const other=s.match(/Your opponent played ([A-HJ][1-9])\./);if(other)apply("O",other[1]);else if(s.includes("Your opponent passed."))apply("O","pass");else throw Error("Missing reply");}
 const shown={};for(const line of s.split("\n")){const m=line.match(/^\s*([1-9])\s+([.XO](?:\s+[.XO]){8})\s+[1-9]\s*$/);if(m){const row=m[2].split(/\s+/);for(let x=0;x<9;x++)shown[cols[x]+m[1]]=row[x];}}
 if(Object.keys(shown).length!==81||points.some(p=>b[p]!==shown[p]))throw Error("Raw board mismatch "+i);
 const next=+s.match(/Move number: (\d+)/)[1],cap=s.match(/Captured by Black: (\d+); by White: (\d+)/),shownKo=s.match(/Ko point: ([^.]+)\./)[1];
 if(next!==moves.length+1||+cap[1]!==captures.X||+cap[2]!==captures.O||shownKo!==(ko||"none"))throw Error("Metadata mismatch "+i);
 checks.push({raw:i,nextMove:next,captures:{...captures},ko});
 }
 return{moves,events,checks,totalMoves:moves.length,totalRawBoards:records.length,captures,allMatched:true};
}

